def analyze(g):
 from collections import Counter,deque
 h,w=len(g),len(g[0]); bg=Counter(sum(g,[])).most_common(1)[0][0]; seen=set(); ret=[]
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if col==bg or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    y,x=q.pop();cells.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==col: seen.add((yy,xx));q.append((yy,xx))
   if len(cells)==1:
    y,x=cells[0]; ns=[g[yy][xx] for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)) if 0<=yy<h and 0<=xx<w]
    ret.append((y,x,col,Counter(ns)))
 return bg,ret
